namespace ShipmentTracker.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime CreatedAt { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public string Status { get; set; } = string.Empty;
    public DateTime CreatedAt { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

using ShipmentTracker.Models;

namespace ShipmentTracker.Services;

public class ShipmentService
{
    private readonly List<Shipment> _shipments = new()
    {
        new Shipment { Id = 1, TrackingNumber = "TRK-20260701-001", Origin = "New York, US", Destination = "London, UK", Status = ShipmentStatus.InTransit, CreatedAt = new DateTime(2026, 7, 1), EstimatedDelivery = new DateTime(2026, 7, 9), CustomerEmail = "alice@example.com", Description = "Electronics - 2 boxes" },
        new Shipment { Id = 2, TrackingNumber = "TRK-20260702-002", Origin = "Tokyo, JP", Destination = "Sydney, AU", Status = ShipmentStatus.OutForDelivery, CreatedAt = new DateTime(2026, 7, 2), EstimatedDelivery = new DateTime(2026, 7, 7), CustomerEmail = "bob@example.com", Description = "Furniture - 1 pallet" },
        new Shipment { Id = 3, TrackingNumber = "TRK-20260703-003", Origin = "Berlin, DE", Destination = "São Paulo, BR", Status = ShipmentStatus.Pending, CreatedAt = new DateTime(2026, 7, 3), EstimatedDelivery = new DateTime(2026, 7, 14), CustomerEmail = "carlos@example.com", Description = "Auto parts - 5 crates" },
        new Shipment { Id = 4, TrackingNumber = "TRK-20260704-004", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = ShipmentStatus.Delivered, CreatedAt = new DateTime(2026, 6, 25), EstimatedDelivery = new DateTime(2026, 7, 5), CustomerEmail = "alice@example.com", Description = "Clothing - 10 boxes" },
        new Shipment { Id = 5, TrackingNumber = "TRK-20260705-005", Origin = "Mumbai, IN", Destination = "Dubai, AE", Status = ShipmentStatus.Delayed, CreatedAt = new DateTime(2026, 7, 1), EstimatedDelivery = new DateTime(2026, 7, 10), CustomerEmail = "fatima@example.com", Description = "Textiles - 3 rolls" },
    };

    private int _nextId = 6;

    public List<ShipmentDto> GetAllShipments()
    {
        return _shipments.Select(ToDto).ToList();
    }

    public List<ShipmentDto> GetShipmentsByCustomer(string email)
    {
        return _shipments
            .Where(s => s.CustomerEmail.Equals(email, StringComparison.OrdinalIgnoreCase))
            .Select(ToDto)
            .ToList();
    }

    public ShipmentDto? GetByTrackingNumber(string trackingNumber)
    {
        var shipment = _shipments.FirstOrDefault(s =>
            s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return shipment is null ? null : ToDto(shipment);
    }

    public ShipmentDto? GetById(int id)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        return shipment is null ? null : ToDto(shipment);
    }

    public ShipmentDto CreateShipment(ShipmentDto dto)
    {
        var shipment = new Shipment
        {
            Id = _nextId++,
            TrackingNumber = $"TRK-{DateTime.UtcNow:yyyyMMdd}-{_nextId:D3}",
            Origin = dto.Origin,
            Destination = dto.Destination,
            Status = ShipmentStatus.Pending,
            CreatedAt = DateTime.UtcNow,
            EstimatedDelivery = dto.EstimatedDelivery,
            CustomerEmail = dto.CustomerEmail,
            Description = dto.Description
        };
        _shipments.Add(shipment);
        return ToDto(shipment);
    }

    public ShipmentDto? UpdateStatus(int id, string status)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment is null) return null;

        if (Enum.TryParse<ShipmentStatus>(status, true, out var parsed))
        {
            shipment.Status = parsed;
        }
        return ToDto(shipment);
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status.ToString(),
        CreatedAt = s.CreatedAt,
        EstimatedDelivery = s.EstimatedDelivery,
        CustomerEmail = s.CustomerEmail,
        Description = s.Description
    };
}

using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using ShipmentTracker.Models;
using ShipmentTracker.Services;

namespace ShipmentTracker.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize]
public class ShipmentsController : ControllerBase
{
    private readonly ShipmentService _service;

    public ShipmentsController(ShipmentService service)
    {
        _service = service;
    }

    [HttpGet]
    public ActionResult<List<ShipmentDto>> GetAll()
    {
        return _service.GetAllShipments();
    }

    [HttpGet("{id:int}")]
    public ActionResult<ShipmentDto> GetById(int id)
    {
        var shipment = _service.GetById(id);
        return shipment is null ? NotFound() : shipment;
    }

    [HttpGet("track/{trackingNumber}")]
    public ActionResult<ShipmentDto> GetByTracking(string trackingNumber)
    {
        var shipment = _service.GetByTrackingNumber(trackingNumber);
        return shipment is null ? NotFound() : shipment;
    }

    [HttpGet("customer/{email}")]
    public ActionResult<List<ShipmentDto>> GetByCustomer(string email)
    {
        return _service.GetShipmentsByCustomer(email);
    }

    [HttpPost]
    public ActionResult<ShipmentDto> Create(ShipmentDto dto)
    {
        var created = _service.CreateShipment(dto);
        return CreatedAtAction(nameof(GetById), new { id = created.Id }, created);
    }

    [HttpPut("{id:int}/status")]
    public ActionResult<ShipmentDto> UpdateStatus(int id, [FromBody] StatusUpdateRequest request)
    {
        var updated = _service.UpdateStatus(id, request.Status);
        return updated is null ? NotFound() : updated;
    }
}

public record StatusUpdateRequest(string Status);

