using System.Net.Http.Json;
using ShipmentTracker.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentClientService
{
    private readonly HttpClient _http;

    public ShipmentClientService(HttpClient http)
    {
        _http = http;
    }

    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await _http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments") ?? new();
    }

    public async Task<ShipmentDto?> TrackShipmentAsync(string trackingNumber)
    {
        var response = await _http.GetAsync($"api/shipments/track/{trackingNumber}");
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<ShipmentDto>();
    }

    public async Task<List<ShipmentDto>> GetMyShipmentsAsync(string email)
    {
        return await _http.GetFromJsonAsync<List<ShipmentDto>>($"api/shipments/customer/{email}") ?? new();
    }

    public async Task<ShipmentDto?> CreateShipmentAsync(ShipmentDto dto)
    {
        var response = await _http.PostAsJsonAsync("api/shipments", dto);
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<ShipmentDto>();
    }

    public async Task<ShipmentDto?> UpdateStatusAsync(int id, string status)
    {
        var response = await _http.PutAsJsonAsync($"api/shipments/{id}/status", new { Status = status });
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<ShipmentDto>();
    }
}

@page "/shipments"
@using ShipmentTracker.Client.Services
@using ShipmentTracker.Models
@inject ShipmentClientService ShipmentService
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@rendermode InteractiveAuto

<PageTitle>Dispatch Board</PageTitle>

<h3>📦 Dispatch Board</h3>

<div class="mb-3 row">
    <div class="col-md-4">
        <input class="form-control" placeholder="Filter by destination..." @bind="filterText" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            <option value="Pending">Pending</option>
            <option value="PickedUp">Picked Up</option>
            <option value="InTransit">In Transit</option>
            <option value="OutForDelivery">Out for Delivery</option>
            <option value="Delivered">Delivered</option>
            <option value="Delayed">Delayed</option>
        </select>
    </div>
    <div class="col-md-3">
        <button class="btn btn-primary" @onclick="ShowCreateForm">+ New Shipment</button>
    </div>
</div>

@if (showCreate)
{
    <div class="card mb-3 p-3">
        <h5>Create Shipment</h5>
        <div class="row g-2">
            <div class="col-md-3">
                <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
            </div>
            <div class="col-md-3">
                <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
            </div>
            <div class="col-md-3">
                <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
            </div>
            <div class="col-md-3">
                <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
            </div>
        </div>
        <div class="mt-2">
            <button class="btn btn-success btn-sm" @onclick="CreateShipment">Save</button>
            <button class="btn btn-secondary btn-sm" @onclick="() => showCreate = false">Cancel</button>
        </div>
    </div>
}

@if (shipments is null)
{
    <p>Loading shipments...</p>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in FilteredShipments)
            {
