@page "/shipments"
@using ShipmentTracker.Client.Services
@using ShipmentTracker.Models
@inject ShipmentClientService ShipmentService
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@rendermode InteractiveAuto

<PageTitle>Dispatch Board</PageTitle>

<h3>📦 Dispatch Board</h3>

<div class="mb-3 row">
    <div class="col-md-4">
        <input class="form-control" placeholder="Filter by destination..." @bind="filterText" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            <option value="Pending">Pending</option>
            <option value="PickedUp">Picked Up</option>
            <option value="InTransit">In Transit</option>
            <option value="OutForDelivery">Out for Delivery</option>
            <option value="Delivered">Delivered</option>
            <option value="Delayed">Delayed</option>
        </select>
    </div>
    <div class="col-md-3">
        <button class="btn btn-primary" @onclick="ShowCreateForm">+ New Shipment</button>
    </div>
</div>

@if (showCreate)
{
    <div class="card mb-3 p-3">
        <h5>Create Shipment</h5>
        <div class="row g-2">
            <div class="col-md-3">
                <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
            </div>
            <div class="col-md-3">
                <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
            </div>
            <div class="col-md-3">
                <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
            </div>
            <div class="col-md-3">
                <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
            </div>
        </div>
        <div class="mt-2">
            <button class="btn btn-success btn-sm" @onclick="CreateShipment">Save</button>
            <button class="btn btn-secondary btn-sm" @onclick="() => showCreate = false">Cancel</button>
        </div>
    </div>
}

@if (shipments is null)
{
    <p>Loading shipments...</p>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in FilteredShipments)
            {
                <tr>
                    <td><code>@s.TrackingNumber</code></td>
                    <td>@s.Origin</td>
                    <td>@s.Destination</td>
                    <td><span class="badge @GetStatusBadge(s.Status)">@s.Status</span></td>
                    <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                    <td>
                        <select class="form-select form-select-sm d-inline-block w-auto"
                                value="@s.Status"
                                @onchange="e => UpdateStatus(s.Id, e.Value?.ToString() ?? s.Status)">
                            <option value="Pending">Pending</option>
                            <option value="PickedUp">Picked Up</option>
                            <option value="InTransit">In Transit</option>
                            <option value="OutForDelivery">Out for Delivery</option>
                            <option value="Delivered">Delivered</option>
                            <option value="Delayed">Delayed</option>
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = "";
    private string statusFilter = "";
    private bool showCreate;
    private ShipmentDto newShipment = new();

    private IEnumerable<ShipmentDto> FilteredShipments => shipments!
        .Where(s => string.IsNullOrEmpty(filterText) || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase))
        .Where(s => string.IsNullOrEmpty(statusFilter) || s.Status == statusFilter);

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ShowCreateForm()
    {
        showCreate = true;
        newShipment = new ShipmentDto { EstimatedDelivery = DateTime.UtcNow.AddDays(7) };
    }

    private async Task CreateShipment()
    {
        var created = await ShipmentService.CreateShipmentAsync(newShipment);
        if (created is not null)
        {
            shipments?.Add(created);
            showCreate = false;
        }
    }

    private async Task UpdateStatus(int id, string status)
    {
        var updated = await ShipmentService.UpdateStatusAsync(id, status);
        if (updated is not null && shipments is not null)
        {
            var index = shipments.FindIndex(s => s.Id == id);
            if (index >= 0) shipments[index] = updated;
        }
    }

    private string GetStatusBadge(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Delayed" => "bg-danger",
        _ => "bg-secondary"
    };
}

